        invFact[n + 1] = modPow(fact[n + 1], MOD - 2);
        for (int i = n; i >= 0; i--) invFact[i] = invFact[i + 1] * (i + 1) % MOD;

        int outside = l + (n - r); // elements outside the duplicated segment [l..r]

        StringBuilder sb = new StringBuilder();
        for (int k = 1; k <= n + 1; k++) {
